SELECT * FROM nw_file_node
WHERE parent_id = #{parentId}
  AND tenant_id = #{tenantId}
  AND deleted = 0
ORDER BY node_type DESC, sort ASC, name ASC

SELECT * FROM nw_file_node
WHERE deleted = 0 AND node_type = 'folder' AND parent_id = '0'
AND created_by = #{createdBy}
AND tenant_id = #{tenantId}
LIMIT 1
